import{_ as a,o as t,c as o,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const h=JSON.parse('{"title":"Documentation projection operations","description":"Build, validate, and review the same-site documentation projection without creating a second source of truth.","frontmatter":{"title":"Documentation projection operations","description":"Build, validate, and review the same-site documentation projection without creating a second source of truth."},"headers":[],"relativePath":"operations/documentation-projection.md","filePath":"operations/documentation-projection.md","lastUpdated":1788519103000}'),n={name:"operations/documentation-projection.md"};function s(r,e,d,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="documentation-projection-operations" tabindex="-1">Documentation projection operations <a class="header-anchor" href="#documentation-projection-operations" aria-label="Permalink to &quot;Documentation projection operations&quot;">​</a></h1><p>The repository Markdown and structured registries under <code>docs/</code> are canonical. VitePress renders a searchable projection at <code>/docs/</code>; generated HTML and copied JSON in <code>dist/docs/</code> are disposable build output and must not be edited or committed.</p><h2 id="build-contract" tabindex="-1">Build contract <a class="header-anchor" href="#build-contract" aria-label="Permalink to &quot;Build contract&quot;">​</a></h2><p>Run the complete local site build from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The command builds the existing landing site first, adds the documentation under <code>dist/docs/</code>, and then checks that every existing <code>public/</code> artifact is still present byte-for-byte. It also verifies every stable computation route and every structured reference copy.</p><p>For documentation-only iteration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check-output</span></span></code></pre></div><p><code>npm run build:docs</code> parses every included Mermaid fence before rendering. A diagram syntax error fails the build instead of reaching publication as a broken figure.</p><h2 id="public-source-boundary" tabindex="-1">Public-source boundary <a class="header-anchor" href="#public-source-boundary" aria-label="Permalink to &quot;Public-source boundary&quot;">​</a></h2><p>The projection includes maintained computation references, provenance records, selected decisions, contributor guidance, and operational contracts. It excludes:</p><ul><li>historical <code>plans/</code>, <code>specs/</code>, and <code>tracking/</code> trees;</li><li>generated feed documentation and runtime calendar payloads;</li><li>repository working notes such as <code>NOW.md</code>, <code>GUIDELINES.md</code>, and the maintainer-only reference status index;</li><li>local UI-review screenshots;</li><li>ignored local output.</li></ul><p>Links from included documents to excluded repository material remain explicit GitHub source links. The projection does not copy that material into the search index.</p><h2 id="computation-routes-and-data" tabindex="-1">Computation routes and data <a class="header-anchor" href="#computation-routes-and-data" aria-label="Permalink to &quot;Computation routes and data&quot;">​</a></h2><p><code>docs/reference/computations.json</code> creates one stable route per computation at <code>/docs/computations/&lt;id&gt;/</code>. Each page labels documentation, regression coverage, and independent source support separately. The build also exposes exact copies of the maintained JSON registries under <code>/docs/reference/</code> for traceability.</p><h2 id="application-navigation" tabindex="-1">Application navigation <a class="header-anchor" href="#application-navigation" aria-label="Permalink to &quot;Application navigation&quot;">​</a></h2><p>The shared desktop sidebar and mobile navigation drawer expose one <strong>Documentation</strong> link to <code>/docs/</code>. Calculation screens remain focused on their results; they do not embed documentation inventories or verification panels.</p><h2 id="publication-boundary" tabindex="-1">Publication boundary <a class="header-anchor" href="#publication-boundary" aria-label="Permalink to &quot;Publication boundary&quot;">​</a></h2><p>The documentation build deliberately adds no deploy workflow, <code>CNAME</code>, DNS record, or second Pages writer. Publishing it requires a separately reviewed, minimal change to the existing Pages workflow after the local screenshots and navigation checks have owner approval. Until then, this is a local build only.</p>`,19)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
